import { FilterForm } from 'models';
import {
  BarClickParams,
  ViewByDisabledCondition,
  WaterfallConfig,
} from 'pages/pillars/ValueCreation/PerformanceTool/config/types';

import { hasSpecificValue } from '../utils/resolveCommercialResultsWaterfallOptions';

const BASE_WATERFALL_FILTER_DISABLED_CONDITIONS: ViewByDisabledCondition[] = [
  ({ activeSubFilters }) => activeSubFilters?.waterfall_filter === 'sku',
];

const handleBrandView = ({
  clickedLabel,
  applyDirect,
}: Pick<BarClickParams, 'applyDirect'> & {
  clickedLabel: string | string[];
}) => {
  const brandLabel = Array.isArray(clickedLabel)
    ? clickedLabel[0]
    : clickedLabel;

  applyDirect({ brands: brandLabel });
};

const handleSubBrandView = ({
  clickedLabel,
  applyDirect,
}: Pick<BarClickParams, 'applyDirect'> & {
  clickedLabel: string;
}) => {
  applyDirect({ sub_brands: clickedLabel });
};

const handleRegionView = ({
  clickedLabel,
  applyDirect,
}: Pick<BarClickParams, 'applyDirect'> & {
  clickedLabel: string;
}) => {
  applyDirect({ region: clickedLabel });
};

const handleChannelView = ({
  clickedLabel,
  applyDirect,
}: Pick<BarClickParams, 'applyDirect'> & {
  clickedLabel: string;
}) => {
  applyDirect({ channel: clickedLabel });
};

const handlePackTypeView = ({
  clickedLabel,
  applyDirect,
}: Pick<BarClickParams, 'applyDirect'> & {
  clickedLabel: string;
}) => {
  applyDirect({ pack_type: clickedLabel });
};

const handleSkuView = ({
  clickedLabel,
  applyDirect,
}: Pick<BarClickParams, 'applyDirect'> & {
  clickedLabel: string;
}) => {
  applyDirect({ sku: clickedLabel || 'All' });
};

export const createBaseWaterfallConfig = (
  kpiName: string,
): WaterfallConfig => ({
  kpiName,

  viewByToGrouping: {},

  groupingToViewBy: {},

  isViewByDisabled: (contextKey, activeSubFilters, applied) =>
    BASE_WATERFALL_FILTER_DISABLED_CONDITIONS.some((condition) =>
      condition({ contextKey, activeSubFilters, applied }),
    ),

  handleBarClick: ({
    index,
    labels,
    activeSubFilters,
    applied,
    applyDirect,
    syncWaterfallFilterAfterDrill,
  }: BarClickParams) => {
    const currentView = activeSubFilters?.waterfall_filter as string;

    const clickedLabel = labels?.[index];
    if (
      !clickedLabel &&
      (currentView !== 'sku' || !hasSpecificValue(applied.sku))
    )
      return;

    const handlers: Record<string, VoidFunction> = {
      region: () => handleRegionView({ clickedLabel, applyDirect }),
      brand: () => handleBrandView({ clickedLabel, applyDirect }),
      channel: () => handleChannelView({ clickedLabel, applyDirect }),
      pack_type: () => handlePackTypeView({ clickedLabel, applyDirect }),
      sub_brand: () => handleSubBrandView({ clickedLabel, applyDirect }),
      sku: () => handleSkuView({ clickedLabel, applyDirect }),
    };

    handlers[currentView]?.();
    syncWaterfallFilterAfterDrill?.(currentView, clickedLabel);
  },

  getContextKey: (applied: FilterForm) => {
    if (!applied) {
      return 'global';
    }

    if (hasSpecificValue(applied.sub_brands)) {
      return 'sub_brand';
    }

    if (hasSpecificValue(applied.brands)) {
      return 'brand';
    }

    return 'global';
  },
});
